import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";

import axios from "axios";

function LecionaAula() {
  const { id } = useParams(); // ID do professor
  const [cursos, setCursos] = useState([]);
  const [aulas, setAulas] = useState([]);
  const [materiais, setMateriais] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [novaAula, setNovaAula] = useState({ titulo: "" });
  const [novoMaterial, setNovoMaterial] = useState({ nome: "" });
  const [editandoAula, setEditandoAula] = useState(null);
  const [materialAulaId, setMaterialAulaId] = useState("");

  useEffect(() => {
    const fetchCursos = async () => {
      try {
        const response = await private_api.get(`/professores/${id}/cursos`);
        setCursos(response.data);
      } catch (error) {
        console.error("Erro ao buscar cursos:", error);
      }
    };
    fetchCursos();
  }, [id]);

  useEffect(() => {
    const fetchDadosCurso = async () => {
      if (cursoSelecionado) {
        try {
          const aulasResponse = await axios.get(
            `/api/aulas/curso/${cursoSelecionado}`
          );
          setAulas(aulasResponse.data);
          const materiaisResponse = await axios.get(
            `/api/materiais/curso/${cursoSelecionado}`
          );
          setMateriais(materiaisResponse.data);
        } catch (error) {
          console.error("Erro ao buscar dados do curso:", error);
        }
      }
    };
    fetchDadosCurso();
  }, [cursoSelecionado]);

  const handleAulaSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("titulo", novaAula.titulo);
    formData.append("cursoId", cursoSelecionado);
    formData.append("professorId", id);
    formData.append("video", novaAula.video);

    try {
      await axios.post("/api/aulas", formData);
      const response = await axios.get(`/api/aulas/curso/${cursoSelecionado}`);
      setAulas(response.data);
      setNovaAula({ titulo: "" });
    } catch (error) {
      console.error("Erro ao criar aula:", error);
    }
  };

  const handleMaterialUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("nome", novoMaterial.nome);
    formData.append("cursoId", cursoSelecionado);
    formData.append("arquivo", novoMaterial.arquivo);
    formData.append("aulaId", materialAulaId || "");

    try {
      await axios.post("/api/materiais", formData);
      const response = await axios.get(
        `/api/materiais/curso/${cursoSelecionado}`
      );
      setMateriais(response.data);
      setNovoMaterial({ nome: "" });
      setMaterialAulaId("");
    } catch (error) {
      console.error("Erro ao enviar material:", error);
    }
  };

  const handleEditarAula = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("titulo", editandoAula.titulo);
    if (editandoAula.video instanceof File) {
      formData.append("video", editandoAula.video);
    }

    try {
      await axios.put(`/api/aulas/${editandoAula.id}`, formData);
      const response = await axios.get(`/api/aulas/curso/${cursoSelecionado}`);
      setAulas(response.data);
      setEditandoAula(null);
    } catch (error) {
      console.error("Erro ao editar aula:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h1>Gerenciar Aulas e Materiais</h1>

      <div className="mb-3">
        <label className="form-label">Selecionar Curso</label>
        <select
          className="form-select"
          value={cursoSelecionado}
          onChange={(e) => setCursoSelecionado(e.target.value)}
        >
          <option value="">Selecione um curso</option>
          {cursos.map((curso) => (
            <option key={curso.id} value={curso.id}>
              {curso.nome}
            </option>
          ))}
        </select>
      </div>

      {cursoSelecionado && (
        <>
          <h2>Cadastrar Nova Aula</h2>
          <form onSubmit={handleAulaSubmit} className="mb-4">
            <div className="mb-3">
              <label className="form-label">Título da Aula</label>
              <input
                type="text"
                className="form-control"
                value={novaAula.titulo}
                onChange={(e) =>
                  setNovaAula({ ...novaAula, titulo: e.target.value })
                }
              />
            </div>
            <div className="mb-3">
              <label className="form-label">Vídeo</label>
              <input
                type="file"
                className="form-control"
                onChange={(e) =>
                  setNovaAula({ ...novaAula, video: e.target.files[0] })
                }
              />
            </div>
            <button type="submit" className="btn btn-primary">
              Cadastrar Aula
            </button>
          </form>

          <h2>Enviar Material</h2>
          <form onSubmit={handleMaterialUpload} className="mb-4">
            <div className="mb-3">
              <label className="form-label">Nome do Material</label>
              <input
                type="text"
                className="form-control"
                value={novoMaterial.nome}
                onChange={(e) =>
                  setNovoMaterial({ ...novoMaterial, nome: e.target.value })
                }
              />
            </div>
            <div className="mb-3">
              <label className="form-label">Arquivo</label>
              <input
                type="file"
                className="form-control"
                onChange={(e) =>
                  setNovoMaterial({
                    ...novoMaterial,
                    arquivo: e.target.files[0],
                  })
                }
              />
            </div>
            <div className="mb-3">
              <label className="form-label">Vincular a Aula (opcional)</label>
              <select
                className="form-select"
                value={materialAulaId}
                onChange={(e) => setMaterialAulaId(e.target.value)}
              >
                <option value="">-- Nenhuma --</option>
                {aulas.map((aula) => (
                  <option key={aula.id} value={aula.id}>
                    {aula.titulo}
                  </option>
                ))}
              </select>
            </div>
            <button type="submit" className="btn btn-secondary">
              Enviar Material
            </button>
          </form>

          <h2>Aulas</h2>
          <ul className="list-group mb-4">
            {aulas.map((aula) => (
              <li
                key={aula.id}
                className="list-group-item d-flex justify-content-between align-items-center"
              >
                {editandoAula?.id === aula.id ? (
                  <form onSubmit={handleEditarAula} className="w-100">
                    <input
                      type="text"
                      className="form-control mb-2"
                      value={editandoAula.titulo}
                      onChange={(e) =>
                        setEditandoAula({
                          ...editandoAula,
                          titulo: e.target.value,
                        })
                      }
                    />
                    <input
                      type="file"
                      className="form-control mb-2"
                      onChange={(e) =>
                        setEditandoAula({
                          ...editandoAula,
                          video: e.target.files[0],
                        })
                      }
                    />
                    <button
                      type="submit"
                      className="btn btn-sm btn-success me-2"
                    >
                      Salvar
                    </button>
                    <button
                      type="button"
                      className="btn btn-sm btn-secondary"
                      onClick={() => setEditandoAula(null)}
                    >
                      Cancelar
                    </button>
                  </form>
                ) : (
                  <>
                    <div>
                      <strong>{aula.titulo}</strong>
                      <br />
                      <video controls width="250" src={aula.videoUrl}></video>
                    </div>
                    <button
                      className="btn btn-sm btn-warning"
                      onClick={() => setEditandoAula(aula)}
                    >
                      Editar
                    </button>
                  </>
                )}
              </li>
            ))}
          </ul>

          <h2>Materiais</h2>
          <ul className="list-group">
            {materiais.map((material) => (
              <li key={material.id} className="list-group-item">
                <a
                  href={material.arquivoUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {material.nome}
                </a>
                {material.aulaId && (
                  <span className="ms-2 text-muted">
                    (Aula:{" "}
                    {aulas.find((a) => a.id === material.aulaId)?.titulo ||
                      "Desconhecida"}
                    )
                  </span>
                )}
              </li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

export default LecionaAula;
